func sortArrayByParityII(A []int) []int {
	n := len(A)
	ans := make([]int, n)
	i := 0
	for _, x := range A {
		if x%2 == 0 {
			ans[i] = x
			i += 2
		}
	}
	i = 1
	for _, x := range A {
		if x%2 == 1 {
			ans[i] = x
			i += 2
		}
	}
	return ans
}

class Solution {
  public int[] sortArrayByParityII(int[] A) {
    int n = A.length;
    int[] ans = new int[n];
    int i = 0;
    for (int x : A) {
      if (x % 2 == 0) {
        ans[i] = x;
        i += 2;
      }
    }
    i = 1;
    for (int x : A) {
      if (x % 2 == 1) {
        ans[i] = x;
        i += 2;
      }
    }
    return ans;
  }
}

class Solution:
    def sortArrayByParityII(self, A: List[int]) -> List[int]:
        n = len(A)
        ans = [0] * n
        i = 0
        for x in A:
            if x % 2 == 0:
                ans[i] = x
                i += 2
        i = 1
        for x in A:
            if x % 2 == 1:
                ans[i] = x
                i += 2
        return ans

impl Solution {
  pub fn sort_array_by_parity_ii(a: Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut ans = vec![0; n];
    let mut i = 0;
    for &x in &a {
      if x % 2 == 0 {
        ans[i] = x;
        i += 2;
      }
    }
    let mut i = 1;
    for &x in &a {
      if x % 2 == 1 {
        ans[i] = x;
        i += 2;
      }
    }
    ans
  }
}

const sortArrayByParityII = (A: number[]): number[] => {
  const n = A.length;
  const ans: number[] = new Array(n).fill(0);
  let i = 0;
  for (const x of A) {
    if (x % 2 === 0) {
      ans[i] = x;
      i += 2;
    }
  }
  i = 1;
  for (const x of A) {
    if (x % 2 === 1) {
      ans[i] = x;
      i += 2;
    }
  }
  return ans;
};
